import { type FormEvent, useCallback, useEffect, useState } from 'react'
import { isAxiosError } from 'axios'

import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { StatusBadge } from '../../components/shared/StatusBadge'
import { apiClient, type ConsentDto, type FamilyDto, type MemberDto, type RelationshipDto } from '../../services/apiClient'

export function FamilyPage() {
  const [family, setFamily] = useState<FamilyDto | null>(null)
  const [selected, setSelected] = useState<MemberDto | null>(null)
  const [consents, setConsents] = useState<ConsentDto[]>([])
  const [relationships, setRelationships] = useState<RelationshipDto[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [message, setMessage] = useState('')
  const [invitationToken, setInvitationToken] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const { data } = await apiClient.get<FamilyDto>('/families/me')
      setFamily(data)
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  function getErrorMessage(error: unknown, fallback: string): string {
    if (isAxiosError(error)) {
      const data = error.response?.data as { message?: string; errors?: Record<string, string[]> } | undefined
      if (data?.errors) {
        return Object.values(data.errors).flat().join(' ')
      }
      if (data?.message) {
        return data.message
      }
    }
    return fallback
  }

  async function addMember(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const formElement = event.currentTarget
    const form = new FormData(formElement)
    const displayName = String(form.get('displayName') || '').trim()
    const dateOfBirth = String(form.get('dateOfBirth') || '').trim()

    if (!displayName || !dateOfBirth) {
      setMessage('Please enter a display name and date of birth.')
      return
    }

    const dob = new Date(`${dateOfBirth}T00:00:00Z`)
    const today = new Date()
    today.setUTCHours(0, 0, 0, 0)
    if (dob > today) {
      setMessage('Date of birth cannot be in the future.')
      return
    }

    const adultCutoff = new Date(today)
    adultCutoff.setUTCFullYear(adultCutoff.getUTCFullYear() - 18)
    if (dob <= adultCutoff) {
      setMessage('Minor profile must be under 18 years old. For adults, use the "Invite adult" option below.')
      return
    }

    setIsSubmitting(true)
    setMessage('')
    try {
      await apiClient.post(`/families/${family?.id}/members`, {
        displayName,
        dateOfBirth,
        role: 'MinorMember',
        userId: null,
      })
      formElement.reset()
      setMessage('Minor member added successfully. Category consents default to not set.')
      await load()
    } catch (error) {
      setMessage(getErrorMessage(error, 'Minor member could not be added. Check all fields and retry.'))
    } finally {
      setIsSubmitting(false)
    }
  }

  async function chooseMember(member: MemberDto) {
    setSelected(member)
    setMessage('')
    try {
      const [consentResponse, relationshipResponse] = await Promise.all([
        apiClient.get<ConsentDto[]>(`/members/${member.id}/consents`),
        apiClient.get<RelationshipDto[]>(`/members/${member.id}/relationships`),
      ])
      setConsents(consentResponse.data)
      setRelationships(relationshipResponse.data)
    } catch {
      setConsents([])
      setRelationships([])
      setMessage('Consent or relationship settings are not accessible for this member.')
    }
  }

  async function toggleConsent(consent: ConsentDto) {
    const next = consent.status === 'Granted' ? 'Revoked' : 'Granted'
    try {
      await apiClient.put(`/members/${consent.memberId}/consents/${consent.category}`, { status: next })
      await chooseMember(selected!)
      setMessage('Consent updated and audited.')
    } catch (error) {
      setMessage(getErrorMessage(error, 'Consent transition is not permitted for this profile.'))
    }
  }

  async function removeMember(member: MemberDto) {
    if (!window.confirm(`Remove ${member.displayName}? Linked records may prevent deletion.`)) return
    try {
      await apiClient.delete(`/members/${member.id}`)
      setSelected(null)
      setConsents([])
      setMessage(`Removed ${member.displayName} successfully.`)
      await load()
    } catch (error) {
      setMessage(getErrorMessage(error, 'Member could not be removed.'))
    }
  }

  async function addRelationship(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!selected) return
    const formElement = event.currentTarget
    const form = new FormData(formElement)
    try {
      await apiClient.post(`/members/${selected.id}/relationships`, {
        relatedMemberId: form.get('relatedMemberId'),
        relationshipType: form.get('relationshipType'),
        isBiological: form.get('isBiological') === 'on',
      })
      formElement.reset()
      await chooseMember(selected)
      setMessage('Relationship saved. Biological status is explicit and audited through access controls.')
    } catch (error) {
      setMessage(getErrorMessage(error, 'Relationship could not be saved.'))
    }
  }

  async function reaffirmConsents() {
    if (!selected) return
    try {
      setConsents((await apiClient.post<ConsentDto[]>(`/members/${selected.id}/consents/reaffirm`)).data)
      setMessage('Eligible consent choices reaffirmed by the adult account.')
    } catch (error) {
      setMessage(getErrorMessage(error, 'Only the adult account can reaffirm its own guardian-granted consent.'))
    }
  }

  async function inviteAdult(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const formElement = event.currentTarget
    const form = new FormData(formElement)
    try {
      const { data } = await apiClient.post<{ token: string; expiresAt: string }>(
        `/families/${family?.id}/invitations`,
        { email: form.get('email') }
      )
      setInvitationToken(data.token)
      formElement.reset()
      setMessage(`Invitation created. Share token securely before ${new Date(data.expiresAt).toLocaleString()}.`)
    } catch (error) {
      setMessage(getErrorMessage(error, 'Invitation could not be created.'))
    }
  }

  const todayStr = new Date().toISOString().split('T')[0]

  if (status === 'loading') return <LoadingState label="Loading family profiles" />
  if (status === 'error') return <ErrorState message="Family profiles could not be loaded." onRetry={() => void load()} />
  if (!family) return <EmptyState title="No family profile" message="Create a family through onboarding before managing profiles." />

  return (
    <div className="page-stack">
      <header className="page-header">
        <div>
          <p className="eyebrow">Family administration</p>
          <h1>{family.name}</h1>
          <p>Manage profiles and explicit category-based consent.</p>
        </div>
      </header>

      {message && <p role="status" className="status-banner">{message}</p>}

      <section className="panel">
        <h2>Members</h2>
        <div className="table-scroll">
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Role</th>
                <th>Date of birth</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {family.members.map((member) => (
                <tr key={member.id}>
                  <td>{member.displayName}</td>
                  <td>{member.role}</td>
                  <td>{member.dateOfBirth}</td>
                  <td>
                    <button className="button button--secondary" type="button" onClick={() => void chooseMember(member)}>
                      Consent
                    </button>{' '}
                    <button className="button button--danger" type="button" onClick={() => void removeMember(member)}>
                      Remove
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      <section className="panel">
        <h2>Add minor profile</h2>
        <p>Adult accounts join only through a verified invitation flow; unlinked adult profiles are rejected.</p>
        <form className="form-grid" onSubmit={(event) => void addMember(event)}>
          <label>
            Display name
            <input name="displayName" required minLength={2} maxLength={100} placeholder="e.g. Kasun" />
          </label>
          <label>
            Date of birth
            <input name="dateOfBirth" type="date" max={todayStr} required />
          </label>
          <input name="role" type="hidden" value="MinorMember" />
          <button className="button button--primary" type="submit" disabled={isSubmitting}>
            {isSubmitting ? 'Adding minor…' : 'Add minor'}
          </button>
        </form>
      </section>

      <section className="panel">
        <h2>Invite adult</h2>
        <p>Token works once, for matching signed-in email, for 48 hours.</p>
        <form className="form-grid" onSubmit={(event) => void inviteAdult(event)}>
          <label>
            Adult account email
            <input name="email" type="email" required maxLength={254} placeholder="adult@example.com" />
          </label>
          <button className="button button--primary" type="submit">Create invitation</button>
        </form>
        {invitationToken && (
          <label className="field">
            <span>One-time invitation token</span>
            <input readOnly value={invitationToken} onFocus={(event) => event.currentTarget.select()} />
          </label>
        )}
      </section>

      {selected && (
        <>
          <section className="panel">
            <h2>Consent: {selected.displayName}</h2>
            {consents.some((consent) => consent.status === 'PendingReaffirmation') && (
              <button className="button button--primary" type="button" onClick={() => void reaffirmConsents()}>
                Reaffirm eligible consent
              </button>
            )}
            {consents.length === 0 ? (
              <EmptyState title="No consent settings" message="This profile has no accessible consent categories." />
            ) : (
              <div className="table-scroll">
                <table>
                  <thead>
                    <tr>
                      <th>Category</th>
                      <th>Status</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {consents.map((consent) => (
                      <tr key={consent.id}>
                        <td>{consent.category}</td>
                        <td><StatusBadge status={consent.status} /></td>
                        <td>
                          {consent.status === 'PendingReaffirmation' ? (
                            'Adult reaffirmation required'
                          ) : (
                            <button
                              className="button button--secondary"
                              type="button"
                              onClick={() => void toggleConsent(consent)}
                            >
                              {consent.status === 'Granted' ? 'Revoke' : 'Grant'}
                            </button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </section>

          <section className="panel">
            <h2>Relationships: {selected.displayName}</h2>
            <form className="form-grid" onSubmit={(event) => void addRelationship(event)}>
              <label>
                Related member
                <select name="relatedMemberId" required>
                  <option value="">Select member</option>
                  {family.members
                    .filter((member) => member.id !== selected.id)
                    .map((member) => (
                      <option key={member.id} value={member.id}>
                        {member.displayName}
                      </option>
                    ))}
                </select>
              </label>
              <label>
                Relationship
                <input name="relationshipType" required maxLength={80} placeholder="e.g. parent or sibling" />
              </label>
              <label>
                <input name="isBiological" type="checkbox" /> Biological relationship
              </label>
              <button className="button button--primary" type="submit">Add relationship</button>
            </form>
            {relationships.length === 0 ? (
              <p className="muted">No relationships recorded.</p>
            ) : (
              <div className="table-scroll">
                <table>
                  <thead>
                    <tr>
                      <th>Related member</th>
                      <th>Relationship</th>
                      <th>Biological</th>
                    </tr>
                  </thead>
                  <tbody>
                    {relationships.map((relationship) => (
                      <tr key={relationship.id}>
                        <td>
                          {family.members.find((member) => member.id === relationship.relatedMemberId)?.displayName ??
                            relationship.relatedMemberId}
                        </td>
                        <td>{relationship.relationshipType}</td>
                        <td>{relationship.isBiological ? 'Yes' : 'No'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </section>
        </>
      )}
    </div>
  )
}
